'use client';
import {useState} from 'react';
import type {RecordRow as R} from '@/lib/erp-primitives';
import {day} from '@/lib/erp-primitives';
import {crmPerformance} from '@/lib/crm-commercial';
export default function SalesOverview({records,onActivities,onTarget,canManage,onOpenTarget}:{records:R[];onActivities:(filter:string,start:string,end:string)=>void;onTarget:()=>void;canManage:boolean;onOpenTarget?:(id:string)=>void}){
 const today=day(),[start,setStart]=useState(today.slice(0,7)+'-01'),[end,setEnd]=useState(today);
 const summary=crmPerformance(records,start,end,today),fmt=(v:number)=>new Intl.NumberFormat('en-UG').format(v);
 return <details className="crm-sales-overview"><summary>Sales overview and targets</summary><div className="crm-overview-period"><label>Period start<input type="date" value={start} max={end} onChange={e=>setStart(e.target.value)}/></label><label>Period end<input type="date" value={end} min={start} onChange={e=>setEnd(e.target.value)}/></label>{canManage&&<button type="button" className="secondary" onClick={onTarget}>Set sales target</button>}</div><div className="crm-metric-buttons">{[['Overdue',summary.overdue],['Due today',summary.dueToday],['Upcoming',summary.upcoming],['Completed in period',summary.completed]].map(([label,count])=><button type="button" key={label} className="secondary" onClick={()=>onActivities(String(label),start,end)}><span>{label}</span><strong>{count}</strong><small>View activities</small></button>)}</div><h3>Won contract value by owner</h3><p>Contract value is separate from earned revenue and cash received.</p><div className="tablebox"><table><thead><tr><th>Owner</th><th>Won deals</th><th>Contract value UGX</th><th>Average sales cycle</th></tr></thead><tbody>{summary.leaders.map(r=><tr key={r.id}><td>{r.name}</td><td>{r.count}</td><td>{fmt(r.value)}</td><td>{r.cycleDays===null?'Not recorded':r.cycleDays+' days'}</td></tr>)}</tbody></table></div>{!summary.leaders.length&&<p>No recorded wins in this period.</p>}{summary.missingCloseDates>0&&<p>{summary.missingCloseDates} historical wins have no recorded close timestamp and are excluded from period results.</p>}<h3>Targets for the selected period</h3>{!summary.targets.length&&<p>No target set for these dates.</p>}{summary.targets.map(target=>{const own=summary.won.filter(r=>r.company===target.company&&(!target.crmOwnerId||r.crmOwnerId===target.crmOwnerId)),value=own.reduce((n,r)=>n+r.amount,0),progress=target.targetContractValue>0?Math.round(value/target.targetContractValue*100):null;return <article key={target.id} className="crm-target-row"><strong>{target.company} · {target.name}</strong>{canManage&&onOpenTarget&&<button type="button" className="textbutton" onClick={()=>onOpenTarget(target.id)}>Edit target</button>}<p>{target.crmOwnerId?target.owner:'Company target'} · UGX {fmt(value)} of {fmt(target.targetContractValue)} · {progress===null?'No value target':progress+'%'} · {own.length} of {target.targetWonDealsCount||'No'} won deal target</p>{progress!==null&&<progress aria-label={target.name+' contract value progress'} max={100} value={Math.min(100,Math.max(0,progress))}/>}</article>})}</details>;
}
